// Validates the incoming webhook payload before entering the loop.
// Expects: { "clusters": [ { "cluster_id": "...", "reviews": [ {id, text, rating}, ... ] }, ... ] }
const body = $input.item.json.body;

if (!body || !Array.isArray(body.clusters)) {
  throw new Error(
    "Invalid payload: expected { clusters: [ { cluster_id, reviews: [...] }, ... ] }. " +
    "Got: " + JSON.stringify(body).slice(0, 200)
  );
}

if (body.clusters.length === 0) {
  throw new Error("Payload has zero clusters — nothing to process.");
}

// Split In Batches expects one item per array entry, so return each cluster as its own item.
return body.clusters.map(cluster => ({ json: cluster }));

// Runs once per loop iteration (one cluster).
// Samples up to 8 reviews for the LLM, but keeps the FULL cluster membership
// separately — this is what fixes the evidence_ids problem: the LLM only
// needs a readable sample to name the theme, but eval-grade evidence_ids
// come from deterministic cluster membership, not from what the LLM read.

const cluster = $input.item.json;
const allReviews = cluster.reviews || [];

if (allReviews.length === 0) {
  throw new Error(`Cluster ${cluster.cluster_id} has zero reviews — check upstream clustering output.`);
}

const sample = allReviews.slice(0, 8);

const formattedText = sample
  .map(r => `[${r.id}] (rating: ${r.rating ?? "n/a"}) ${r.text}`)
  .join("\n\n");

return [{
  json: {
    cluster_id: cluster.cluster_id,
    sample_text: formattedText,
    sample_ids: sample.map(r => r.id),
    all_cluster_member_ids: allReviews.map(r => r.id),   // full evidence set, deterministic
    all_cluster_reviews: allReviews                        // kept for the evidence validator step
  }
}];

// Reshapes the 3 merged spoke outputs into one object the Synthesizer agent can read.
const merged = $input.item.json;
return [{
  json: {
    theme_output: merged.output ?? merged['0'] ?? merged,
    jtbd_output: merged['1'] ?? null,
    opportunity_output: merged['2'] ?? null
  }
}];
// NOTE: exact merged-item shape depends on your n8n version's merge node output format.
// Inspect one execution in the n8n UI and adjust field access here if needed.

// Deterministic validation — never trust the LLM to grade itself.
// 1. Confirms every evidence ID the agents cited actually exists in this cluster.
// 2. Replaces the theme's evidence_ids with the FULL deterministic cluster
//    membership (not just the LLM's sample) — this is what satisfies the
//    blueprint's D.2 eval requirement of >30 evidence reviews per theme.
// 3. Flags (does not silently drop) any hallucinated IDs for the pipeline_errors log.

const synthesized = $input.item.json.output ?? $input.item.json; // handle either raw or wrapped agent output
const clusterData = $('Prepare Cluster Text').item.json;

let parsed;
try {
  parsed = typeof synthesized === "string" ? JSON.parse(synthesized) : synthesized;
} catch (e) {
  return [{
    json: {
      cluster_id: clusterData.cluster_id,
      validation_error: `Failed to parse synthesizer output as JSON: ${e.message}`,
      raw_output: synthesized
    }
  }];
}

const validClusterIds = new Set(clusterData.all_cluster_member_ids);
const citedIds = parsed.sample_evidence_ids || [];
const hallucinatedIds = citedIds.filter(id => !validClusterIds.has(id));

const result = {
  ...parsed,
  cluster_id: clusterData.cluster_id,
  // Evidence for eval purposes = full deterministic cluster membership, not just LLM sample.
  evidence_ids: clusterData.all_cluster_member_ids,
  evidence_count: clusterData.all_cluster_member_ids.length,
  llm_hallucinated_ids: hallucinatedIds,
  validation_passed: hallucinatedIds.length === 0
};

return [{ json: result }];

// Runs once, after Split In Batches' "done" output fires (all clusters processed).
// Collects every validated theme object emitted so far in this execution.
const allItems = $input.all();
const themes = allItems.map(item => item.json);

const validCount = themes.filter(t => t.validation_passed).length;
const hallucinationRate = themes.length > 0
  ? ((themes.length - validCount) / themes.length * 100).toFixed(1)
  : "0.0";

return [{
  json: {
    generated_at: new Date().toISOString(),
    total_clusters_processed: themes.length,
    hallucination_rate_pct: hallucinationRate,
    themes: themes
  }
}];

// Token-aware rate-limit pacing — replaces the flat 2s Wait node.
// Estimates tokens used by THIS cluster's 4 LLM calls (Theme, JTBD,
// Opportunity, Orchestrator Synthesizer) from the actual sample_text sent,
// tracks a rolling 60s token window in workflow static data, and computes
// how long to wait before the next cluster so the rolling window stays
// under TPM_BUDGET. See docs/GROQ_MIGRATION_AND_FAILPROOFING.md for the
// math this is based on (~2,800-4,400 tokens/cluster against a 6k-12k TPM
// range) — these are starting estimates, not guarantees. Watch actual token
// usage on console.groq.com during the first real run and tighten
// TPM_BUDGET down if you still hit 429s.

const TPM_BUDGET = 6000;              // conservative end of Groq's published range
const CHARS_PER_TOKEN = 4;            // rough estimate for English text
const OVERHEAD_TOKENS_PER_CALL = 400; // system prompt + JSON scaffolding, per call

const clusterData = $('Prepare Cluster Text').item.json;
const sampleText = clusterData.sample_text || '';
const sampleTokens = Math.ceil(sampleText.length / CHARS_PER_TOKEN);

// Theme, JTBD, and Opportunity agents each read the full sample_text once.
// The Orchestrator instead reads the smaller combined JSON of their 3
// outputs — approximate its cost as one more overhead-sized call rather
// than a full sample_text re-read.
const estimatedTokensThisCluster =
  (sampleTokens + OVERHEAD_TOKENS_PER_CALL) * 3   // Theme + JTBD + Opportunity
  + OVERHEAD_TOKENS_PER_CALL * 2;                 // Orchestrator in + out

const staticData = $getWorkflowStaticData('global');
if (!staticData.tokenWindow) staticData.tokenWindow = [];

const now = Date.now();
// Drop entries older than the 60s rolling window.
staticData.tokenWindow = staticData.tokenWindow.filter((e) => now - e.ts < 60000);

const tokensInWindow = staticData.tokenWindow.reduce((sum, e) => sum + e.tokens, 0);
const projectedTotal = tokensInWindow + estimatedTokensThisCluster;

let waitSeconds = 5; // floor — always leave breathing room between clusters
if (projectedTotal > TPM_BUDGET) {
  // Rough conversion: assume tokens arrived evenly across the window, so
  // waiting (excess / TPM_BUDGET) * 60s lets enough of the window roll off.
  const excess = projectedTotal - TPM_BUDGET;
  waitSeconds = Math.max(waitSeconds, Math.ceil((excess / TPM_BUDGET) * 60));
}
waitSeconds = Math.min(waitSeconds, 90); // sanity cap

staticData.tokenWindow.push({ ts: now, tokens: estimatedTokensThisCluster });

return [{
  json: {
    ...$input.item.json,
    wait_seconds: waitSeconds,
  },
}];
